pub fn bsp_world() -> BspWorld<'static> {
    BspWorld::new(
        &BSP_PLANES,
        &BSP_NODES,
        &BSP_LEAVES,
        &BSP_FACES,
        &BSP_MARKSURFACES,
        &BSP_VERTICES,
        &BSP_UVS,
        &BSP_LM_UVS,
        &BSP_VIS,
        &BSP_VIS_OFFSETS,
        BSP_NUM_CLUSTERS,
    )
}

pub fn bsp_sector_lights() -> &'static [SectorLight] {
    &BSP_SECTOR_LIGHTS
}
pub fn bsp_nav_wall_segments() -> &'static [[f32; 4]] {
    &BSP_NAV_WALL_SEGMENTS
}
pub fn bsp_nav_floor_points() -> &'static [[f32; 2]] {
    &BSP_NAV_FLOOR_POINTS
}
pub fn bsp_nav_floor_regions() -> &'static [NavFloorRegion] {
    &BSP_NAV_FLOOR_REGIONS
}

